                </div>
              </GlassCard>

              {/* Footer status */}
              <div className="mt-4 text-center space-y-1">
                <p className="text-xs text-slate-400">
                  © 2026 FibreFlow. All rights reserved.
                </p>
                <div className="flex items-center justify-center gap-3 text-xs text-slate-400">
