  rules: [
    detectBot({
      mode: "LIVE",
      allow: ["CATEGORY:SEARCH_ENGINE"],
    }),
    fixedWindow({
      mode: "LIVE",
      window: "1m",
      max: 100,
    }),
    shield({
      mode: "LIVE",
    }),
  ],
}) : null;

/**
 * Health check endpoints - Very generous rate limiting: 300 req/min
 * Monitoring systems need frequent access
 */
const ajHealth = ARCJET_KEY ? arcjet({
