import { createContext, useContext, useEffect, useState, ReactNode, useCallback } from 'react';
import { AuthUser } from '@/services/authService';
import {
  User,
  UserRole,
  Permission,
  LoginCredentials,
  RegisterCredentials,
  PasswordResetRequest,
  ChangePasswordRequest,
  ROLE_PERMISSIONS,
} from '@/types/auth.types';
import { resetAuthErrorHandler } from '@/lib/authErrorHandler';

interface AuthContextType {
  // Legacy properties for backward compatibility
  user: AuthUser | null;
  loading: boolean;
  error: string | null;
  signInWithEmail: (email: string, password: string) => Promise<void>;
  signInWithGoogle: () => Promise<void>;
  signUp: (email: string, password: string, displayName?: string) => Promise<void>;
  signOut: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;

  // Enhanced properties with RBAC
  currentUser: User | null;
  isAuthenticated: boolean;
  signInWithEmailEnhanced: (credentials: LoginCredentials) => Promise<void>;
  signInWithGoogleEnhanced: (rememberMe?: boolean) => Promise<void>;
  registerWithEmail: (credentials: RegisterCredentials) => Promise<void>;
  resetPasswordEnhanced: (request: PasswordResetRequest) => Promise<void>;
  changePassword: (request: ChangePasswordRequest) => Promise<void>;
  sendEmailVerification: () => Promise<void>;
  updateProfile: (updates: Partial<User>) => Promise<void>;

  // Permission checking methods
  hasPermission: (permission: Permission) => boolean;
  hasAnyPermission: (permissions: Permission[]) => boolean;
  hasAllPermissions: (permissions: Permission[]) => boolean;
  hasRole: (role: UserRole) => boolean;
  hasAnyRole: (roles: UserRole[]) => boolean;

  // Utility methods
  clearError: () => void;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

// Map API role to UserRole enum
function mapRole(role: string): UserRole {
  const roleMap: Record<string, UserRole> = {
    'system': UserRole.SUPER_ADMIN,
    'super_admin': UserRole.SUPER_ADMIN,
    'admin': UserRole.ADMIN,
    'manager': UserRole.PROJECT_MANAGER,
    'technician': UserRole.FIELD_TECHNICIAN,
    'viewer': UserRole.VIEWER,
  };
  return roleMap[role] || UserRole.VIEWER;
}

// Map API user to internal User type
function mapApiUser(apiUser: {
  id: string;
  email: string;
  name?: string;
  firstName?: string;
  lastName?: string;
  role: string;
  permissions: string[];
  profilePicture?: string | null;
}): { user: User; authUser: AuthUser } {
  const role = mapRole(apiUser.role);
  const permissions = apiUser.permissions.includes('all')
    ? Object.values(Permission)
    : (apiUser.permissions as Permission[]);

  // Build display name from firstName/lastName or fall back to name or email

    } else {
      setUser(null);
      setCurrentUser(null);
      setIsAuthenticated(false);
    }
  } catch {
    setUser(null);
    setCurrentUser(null);
    setIsAuthenticated(false);
  } finally {
    setLoading(false);
  }
}, []);

useEffect(() => {
  checkAuth();

  // Reset the redirect handler when component mounts (in case of page reload after redirect)
  resetAuthErrorHandler();
}, [checkAuth]);

// Legacy sign in method
const signInWithEmail = async (email: string, password: string) => {
  setLoading(true);
  setError(null);

  try {
    const res = await fetch('/api/auth/login', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
      credentials: 'include',
    });

    const data = await res.json();

    if (!res.ok) {
      throw new Error(data.error?.message || data.message || 'Login failed');
    }

    // API returns { success, data: { user } } structure
    const userData = data.data?.user || data.user;
    const { user: mappedUser, authUser } = mapApiUser(userData);
    setUser(authUser);
    setCurrentUser(mappedUser);
    setIsAuthenticated(true);
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Login failed';
    setError(message);
    throw err;
  } finally {
    setLoading(false);
  }
};

const signInWithGoogle = async () => {
  setError('Google sign-in is not available. Please use email/password.');
  throw new Error('Google sign-in not implemented');
};

const signUp = async (_email: string, _password: string, _displayName?: string) => {
  setError('Registration is not available. Please contact an administrator.');
  throw new Error('Registration not implemented');
};

const resetPassword = async (_email: string) => {
  setError('Password reset is not available. Please contact an administrator.');
  throw new Error('Password reset not implemented');
};

// Enhanced methods with RBAC
const signInWithEmailEnhanced = async (credentials: LoginCredentials) => {
  await signInWithEmail(credentials.email, credentials.password);
};

const signInWithGoogleEnhanced = async (_rememberMe = false) => {
  await signInWithGoogle();
};

const registerWithEmail = async (_credentials: RegisterCredentials) => {
  setError('Registration is not available. Please contact an administrator.');
  throw new Error('Registration not implemented');
};

const signOut = async () => {
  try {
    await fetch('/api/auth/logout', {
      method: 'POST',
      credentials: 'include',
    });
  } finally {
    setUser(null);
    setCurrentUser(null);
    setIsAuthenticated(false);
    // Redirect to sign-in page
    if (typeof window !== 'undefined') {
      window.location.href = '/sign-in';
    }
  }
};

const resetPasswordEnhanced = async (_request: PasswordResetRequest) => {
  await resetPassword(_request.email);
};

const changePassword = async (_request: ChangePasswordRequest) => {
  setError('Password change is not available yet.');
  throw new Error('Password change not implemented');
};

const sendEmailVerification = async () => {
  setError('Email verification is not available.');
  throw new Error('Email verification not implemented');
};

const updateProfile = async (_updates: Partial<User>) => {
  setError('Profile update is not available yet.');
  throw new Error('Profile update not implemented');
};

/**
 * Global Auth Error Handler
 *
 * Handles 401 errors by redirecting to sign-in page with return URL.
 * Sets up a global fetch interceptor when imported.
 */

import toast from 'react-hot-toast';

let isRedirecting = false;
let interceptorInstalled = false;

/**
 * Handle authentication error (401) by showing a message and redirecting to sign-in
 * @param options - Optional configuration
 */
export function handleAuthError(options?: {
  showToast?: boolean;
  message?: string;
}) {
  // Prevent multiple redirects
  if (isRedirecting) return;

  if (typeof window === 'undefined') return;

  const currentPath = window.location.pathname + window.location.search;

  // Don't redirect if already on sign-in, auth pages, or fleet portal/check-in (uses plate-based auth)
  if (
    currentPath.startsWith('/sign-in') ||
    currentPath.startsWith('/auth/') ||
    currentPath.startsWith('/fleet/portal') ||
    currentPath.startsWith('/fleet/check-in') ||
    currentPath.startsWith('/fleet/vehicles/')
  ) {
    return;
  }

  isRedirecting = true;

  // Show toast notification - use a gentle notification for timed logout, not error
  if (options?.showToast !== false) {
    toast(options?.message || 'Session timed out. Redirecting to sign in...', {
      duration: 3000,
      id: 'auth-error', // Prevent duplicate toasts
      icon: '⏱️',
      style: {
        background: '#374151', // gray-700
        color: '#f9fafb', // gray-50
        borderRadius: '8px',
      },
    });
  }

  // Small delay to allow toast to be seen
  setTimeout(() => {
    window.location.href = `/sign-in?returnUrl=${encodeURIComponent(currentPath)}`;
  }, 500);
}

/**
 * Wrapper for fetch that handles 401 errors automatically
 */
export async function authFetch(
  input: RequestInfo | URL,
  init?: RequestInit
): Promise<Response> {
  const response = await fetch(input, {
    ...init,
    credentials: 'include', // Always include credentials
  });

  if (response.status === 401) {
    handleAuthError();
    // Return the response anyway so the caller can handle it if needed
  }

  return response;
}

/**
 * Check if a response is a 401 and handle it
 * Use this after any fetch call to handle auth errors
 */
export function checkAuthResponse(response: Response): boolean {
  if (response.status === 401) {
    handleAuthError();
    return true;
  }
  return false;
}

/**
 * Reset the redirect flag (useful for testing)
 */
export function resetAuthErrorHandler() {
  isRedirecting = false;
}

/**
 * Install the global fetch interceptor
 * Safe to call multiple times - only installs once
 */
export function installAuthInterceptor() {
  if (typeof window === 'undefined' || interceptorInstalled) return;

  interceptorInstalled = true;
  const originalFetch = window.fetch;

  window.fetch = async function (...args) {
    const response = await originalFetch.apply(this, args);

    // Handle 401 responses globally (except for auth and portal endpoints)
    if (response.status === 401) {
      const url = typeof args[0] === 'string' ? args[0] : args[0] instanceof Request ? args[0].url : '';
      // Don't redirect for:
      // - Auth check endpoints (expected 401 when not logged in)
      // - Portal endpoints (use plate-based auth, not user auth)
      // - Fleet check-in/vehicle APIs (support portal session auth)
      const isExcludedPath =
        url.includes('/api/auth/me') ||
        url.includes('/api/auth/check-email') ||
        url.includes('/api/fleet/portal/') ||
        url.includes('/api/fleet/check-in/') ||
        url.includes('/api/fleet/vehicles/');

      if (!isExcludedPath) {
        handleAuthError();
      }
    }

    return response;
  };
}

// Auto-install when this module is imported on the client side
if (typeof window !== 'undefined') {
  installAuthInterceptor();
}

